import{_ as o,C as n,o as t,c as i,a2 as r,b as d,w as s,a as l,E as c,a3 as u}from"./chunks/framework.Dd_iHz3e.js";const _=JSON.parse('{"title":"14.7 Messaging, Queues & Asynchronous Processing","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.7-messaging-and-queues.md","filePath":"system-design/14.7-messaging-and-queues.md"}'),g={name:"system-design/14.7-messaging-and-queues.md"};function h(m,e,p,k,f,v){const a=n("Mermaid");return t(),i("div",null,[e[1]||(e[1]=r('<h1 id="_14-7-messaging-queues-asynchronous-processing" tabindex="-1">14.7 Messaging, Queues &amp; Asynchronous Processing <a class="header-anchor" href="#_14-7-messaging-queues-asynchronous-processing" aria-label="Permalink to &quot;14.7 Messaging, Queues &amp; Asynchronous Processing&quot;">​</a></h1><h2 id="_1-plain-english-overview" tabindex="-1">1. Plain English Overview <a class="header-anchor" href="#_1-plain-english-overview" aria-label="Permalink to &quot;1. Plain English Overview&quot;">​</a></h2><p>Message queues and event streams decouple fast client-facing web servers from slow, resource-heavy backend operations (such as video transcoding, sending email notifications, or processing telemetry) by holding jobs in an ordered queue until background workers process them.</p><hr><h2 id="_2-usage-in-cooking-nexus" tabindex="-1">2. Usage in Cooking Nexus <a class="header-anchor" href="#_2-usage-in-cooking-nexus" aria-label="Permalink to &quot;2. Usage in Cooking Nexus&quot;">​</a></h2><ul><li><strong>Current State</strong>: Direct synchronous processing in Express routes ([server.js](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/server.js)).</li><li><strong>Target Asynchronous Pipeline</strong>: Decouple high-frequency <code>/api/vision</code> hazard pings and video upload transcoding into a background worker queue.</li></ul><hr><h2 id="_3-asynchronous-queue-architecture" tabindex="-1">3. Asynchronous Queue Architecture <a class="header-anchor" href="#_3-asynchronous-queue-architecture" aria-label="Permalink to &quot;3. Asynchronous Queue Architecture&quot;">​</a></h2>',8)),(t(),d(u,null,{default:s(()=>[c(a,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Sensor%5B%22Range%20Hood%20Camera%22%5D%20--%3E%7CPOST%20%2Fapi%2Fvision%7C%20API%5B%22Express%20Ingestion%20Server%22%5D%0A%20%20%20%20API%20--%3E%7C1.%20Push%20Event%20to%20Queue%20(%3C2ms)%7C%20Queue%5B%22Redis%20Streams%20%2F%20RabbitMQ%20Queue%22%5D%0A%20%20%20%20API%20--%3E%3E%7C2.%20Immediate%20HTTP%20202%20Accepted%7C%20Sensor%0A%0A%20%20%20%20subgraph%20Workers%20%5B%22Background%20Worker%20Pool%22%5D%0A%20%20%20%20%20%20%20%20Worker1%5B%22Safety%20Worker%201%22%5D%0A%20%20%20%20%20%20%20%20Worker2%5B%22Safety%20Worker%202%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20Queue%20--%3E%20Worker1%20%26%20Worker2%0A%20%20%20%20Worker1%20--%3E%7CBatch%20Write%20(500%20docs)%7C%20Mongo%5B(%22MongoDB%20SafetyLog%22)%5D%0A%20%20%20%20Worker2%20--%3E%7CHigh%20Hazard%20Alert%7C%20PushNotification%5B%22APNs%20%2F%20FCM%20Push%20Notification%22%5D%0A%20%20%20%20Worker1%20-.-%3E%7COn%20Failure%20(3%20retries)%7C%20DLQ%5B%22Dead%20Letter%20Queue%20(DLQ)%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<hr><h2 id="_4-messaging-technologies-comparison" tabindex="-1">4. Messaging Technologies Comparison <a class="header-anchor" href="#_4-messaging-technologies-comparison" aria-label="Permalink to &quot;4. Messaging Technologies Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Technology</th><th>Delivery Model</th><th>Delivery Semantics</th><th>Ordering Guarantees</th><th>Throughput</th><th>Fit for Cooking Nexus</th></tr></thead><tbody><tr><td><strong>Redis Streams (Chosen)</strong></td><td>In-Memory Stream / Consumer Groups</td><td>At-least-once</td><td>Strict FIFO per stream</td><td>Ultra-High (&gt;500k ops/sec)</td><td>Optimal for IoT frame buffering</td></tr><tr><td><strong>RabbitMQ</strong></td><td>Traditional AMQP Message Broker</td><td>At-least-once</td><td>FIFO per queue</td><td>Moderate (~50k msg/sec)</td><td>Great for complex routing keys</td></tr><tr><td><strong>Apache Kafka</strong></td><td>Distributed Commit Log</td><td>At-least-once</td><td>Strict per partition</td><td>Extreme (&gt;1M msg/sec)</td><td>Overkill for early stage</td></tr><tr><td><strong>AWS SQS</strong></td><td>Managed Cloud Queue</td><td>At-least-once</td><td>Standard (Best effort) / FIFO</td><td>High</td><td>Vendor locked, easy setup</td></tr><tr><td><strong>BullMQ (Redis)</strong></td><td>Node.js Redis Job Queue</td><td>At-least-once</td><td>Configurable priority</td><td>High</td><td>Excellent for video transcoding</td></tr></tbody></table><hr><h2 id="_5-delivery-semantics-failure-handling" tabindex="-1">5. Delivery Semantics &amp; Failure Handling <a class="header-anchor" href="#_5-delivery-semantics-failure-handling" aria-label="Permalink to &quot;5. Delivery Semantics &amp; Failure Handling&quot;">​</a></h2><ol><li><strong>At-Least-Once Delivery</strong>: Workers acknowledge messages (<code>XACK</code>) only after the batch insert into MongoDB succeeds. If a worker crashes mid-insert, another worker claims the pending message after a 5-second visibility timeout.</li><li><strong>Idempotent Consumer</strong>: Every safety telemetry payload includes a unique <code>eventUuid</code> generated at the camera. The worker performs an atomic <code>$setOnInsert</code> in MongoDB using the <code>eventUuid</code>, ensuring duplicate message retries never create duplicate safety incident records.</li><li><strong>Dead Letter Queue (DLQ)</strong>: If a corrupted payload fails validation 3 consecutive times, it is routed to a dead letter queue for developer inspection.</li></ol><hr><h2 id="_6-what-breaks-first-at-scale" tabindex="-1">6. What Breaks First at Scale? <a class="header-anchor" href="#_6-what-breaks-first-at-scale" aria-label="Permalink to &quot;6. What Breaks First at Scale?&quot;">​</a></h2><ul><li><strong>At 10x</strong>: Synchronous database writes in <code>/api/vision</code> will block the Express event loop under concurrent load.</li><li><strong>At 100x</strong>: Queue memory overflow in Redis if worker processes halt and messages pile up unchecked.</li><li><strong>At 1,000x</strong>: Partition consumer lag in Kafka if video transcoding workers cannot keep pace with uploaded reels.</li></ul><hr><h2 id="_7-senior-engineer-improvements" tabindex="-1">7. Senior Engineer Improvements <a class="header-anchor" href="#_7-senior-engineer-improvements" aria-label="Permalink to &quot;7. Senior Engineer Improvements&quot;">​</a></h2><p>Implement <strong>Queue Backpressure &amp; Shedding</strong>: If the telemetry queue depth exceeds 50,000 pending items, downsample low-severity normal-temperature pings while giving strict priority to high-severity smoke or flame hazard messages.</p><hr><h2 id="_8-spoken-interview-answer-30-seconds" tabindex="-1">8. Spoken Interview Answer (30 Seconds) <a class="header-anchor" href="#_8-spoken-interview-answer-30-seconds" aria-label="Permalink to &quot;8. Spoken Interview Answer (30 Seconds)&quot;">​</a></h2><p>&quot;To scale kitchen safety telemetry to 10,000 concurrent kitchens, we decouple ingestion from database persistence using Redis Streams. When an optical camera posts a frame to <code>/api/vision</code>, Express immediately pushes the event to the stream and returns an HTTP 202 Accepted in under two milliseconds. Background worker consumers pull events in batches of 500, write them to MongoDB, and trigger push notifications, while an idempotent event UUID ensures that network retries never produce duplicate database entries.&quot;</p>',15))])}const A=o(g,[["render",h]]);export{_ as __pageData,A as default};
